<?php
function sb_assets(){echo '<link rel="stylesheet" href="assets/overview_reports.css?v=5.9.17"><link rel="stylesheet" href="assets/balance_reports.css?v=5.9.18"><script src="assets/balance_reports.js?v=5.9.18" defer></script>';}
function sb_query($f){return array_replace(report_public_filters($f),['page'=>'reports']);}
function sb_nav($f){echo '<div class="page-head"><div><h1>Reports</h1><p>Read-only stock balances and operational records.</p></div></div><div class="tabs report-tabs">';foreach(access_report_catalog() as $group=>$reports)echo '<a class="tab '.($group==='Stock Balances'?'active':'').'" href="?'.e(http_build_query(array_replace(sb_query($f),['report'=>array_key_first($reports),'offset'=>0]))).'">'.e($group).'</a>';echo '</div>';}
function sb_subtabs($f){echo '<div class="sb-subtabs">';foreach(['stocks'=>'Stock Balance','platforms'=>'Platform Inventory','restricted'=>'Non-Sellable','product_master'=>'Product Master'] as $key=>$label){if(!access_report_allowed($key))continue;$params=array_replace(sb_query($f),['report'=>$key,'offset'=>0]);if($key==='product_master')unset($params['balance_filter']);else $params['as_of']=$f['as_of']??date('Y-m-d');echo '<a class="btn '.($f['report']===$key?'primary':'ghost').'" href="?'.e(http_build_query($params)).'"'.($f['report']===$key?' aria-current="page"':'').'>'.$label.'</a>';}echo '</div>';}
function sb_cards($summary){if(!$summary)return;echo '<div class="overview-ending sb-ending">';$i=0;foreach($summary as $label=>$qty){echo '<div class="overview-total '.($i===2?'overview-physical':'').'"><span>'.e(str_replace(' (pcs)','',$label)).'</span><strong class="'.($qty<0?'sb-negative':'').'">'.number_format($qty).'</strong><small>pcs · '.e(['Includes reserved stock still in warehouse','Damage / Leak / For Repackaging / other','Sellable + Non-Sellable'][$i]).'</small></div>';$i++;}echo '</div>';}
function sb_exports($r){$params=report_public_filters($r['filters']);echo '<div class="overview-actions"><a class="btn secondary" href="report.php?'.e(http_build_query($params+['format'=>'xlsx'])).'">Download Excel</a><a class="btn ghost" target="_blank" rel="noopener" href="report.php?'.e(http_build_query($params+['format'=>'print'])).'">Print / Save as PDF</a></div>';}
function sb_pager($count,$size,$offset,$params){$pager=rs8_pagination($count,$offset,$size,array_replace($params,['per_page'=>$size]),'offset',false,'Totals and exports include every matching row across all pages.');$label='<label class="overview-size"><select data-sb-size aria-label="Rows per page">';foreach([10,20,30,50] as $n)$label.='<option value="'.$n.'"'.($n===$size?' selected':'').'>'.$n.'</option>';$label.='</select><span>Rows per page</span></label>';echo str_replace('</span></div><div class="pagination-buttons">','</span>'.$label.'</div><div class="pagination-buttons">',$pager);}
function sb_notes_html($notes){echo '<div class="sb-notes">';foreach($notes as $note)echo '<p class="small muted">'.e($note).'</p>';echo '</div>';}
function sb_render_sources($r){
 $sections=sb_source_section($r);$sourceCount=count($sections['rows']);$sourceOffset=sb_offset($sourceCount,10,$_GET['sb_source_offset']??0);echo '<details class="card sb-sources"'.(isset($_GET['sb_source_offset'])?' open':'').'><summary>Non-Sellable Source Records</summary><p class="small muted">Source-record availability may be unverified for legacy releases without complete links. Ledger totals remain the reference for stock quantities.</p><div class="overview-table-scroll"><table class="table" data-server-paginated="1"><thead><tr>';foreach($sections['headers'] as $h)echo '<th>'.e($h).'</th>';echo '</tr></thead><tbody>';
 foreach(array_slice($sections['rows'],$sourceOffset,10) as $row){echo '<tr>';foreach($row as $v)echo '<td'.(is_int($v)?' class="overview-number"':'').'>'.e(is_int($v)?number_format($v):$v).'</td>';echo '</tr>';}if(!$sections['rows'])echo '<tr><td colspan="'.count($sections['headers']).'">No open source records at this cutoff. Review Movement History for all receipts and releases.</td></tr>';echo '</tbody></table></div>'.rs8_pagination($sourceCount,$sourceOffset,10,$_GET,'sb_source_offset',false,'10 source records per page · Downloads include all matching source records.').'</details>';
}
function sb_report_page($r){
 $f=$r['filters'];$key=$f['report'];$master=$key==='product_master';$count=count($r['rows']);$size=sb_page_size();$offset=sb_offset($count,$size);$query=sb_query($f);sb_assets();echo '<div class="overview-report sb-report">';sb_nav($f);echo '<div class="overview-title"><h2>'.e($r['title']).'</h2><p>'.($master?'Current product descriptions and status.':'Posted quantities through the selected As Of date.').'</p></div>';sb_subtabs($f);
 echo '<div class="card"><form method="get" class="overview-filters sb-filters" data-sb-filters><input type="hidden" name="page" value="reports"><input type="hidden" name="report" value="'.e($key).'"><input type="hidden" name="per_page" value="'.$size.'"><label>Product / SKU<select name="product_id" data-product-select><option value="0">All Products</option>';
 foreach(db()->query('SELECT id,name,master_sku,brand FROM products ORDER BY name,id') as $p)echo '<option value="'.(int)$p['id'].'" '.((int)$f['product_id']===(int)$p['id']?'selected':'').'>'.e($p['name'].' · '.$p['brand'].' · '.$p['master_sku']).'</option>';
 echo '</select></label><label>As Of Date<input type="date" name="as_of" value="'.e($f['as_of']??date('Y-m-d')).'" max="'.date('Y-m-d').'" '.($master?'disabled':'required').'></label><label>'.($master?'Product Status':'Quantity Filter').'<select name="'.($master?'product_status':'balance_filter').'">';
 $options=$master?['all'=>'All Products','active'=>'Active','inactive'=>'Inactive']:sb_filter_labels();$selected=$master?$f['product_status']:($f['balance_filter']??'all');foreach($options as $value=>$label)echo '<option value="'.$value.'"'.($selected===$value?' selected':'').'>'.$label.'</option>';echo '</select></label><label>Brand<select name="brand"><option value="">All Brands</option>';
 foreach(inventory_brand_options() as $brand)echo '<option '.($f['brand']===$brand?'selected':'').'>'.e($brand).'</option>';echo '</select></label><label>Main Category<select name="main_category"><option value="">All Main Categories</option>';$tree=product_category_tree();foreach($tree as $main=>$subs)echo '<option '.($f['main_category']===$main?'selected':'').'>'.e($main).'</option>';echo '</select></label><label>Subcategory<select name="subcategory"><option value="">All Subcategories</option>';$subs=[];foreach($tree as $main=>$values)if(!$f['main_category']||$f['main_category']===$main)$subs=array_merge($subs,$values);foreach(array_unique($subs) as $sub)echo '<option '.($f['subcategory']===$sub?'selected':'').'>'.e($sub).'</option>';echo '</select></label>';
 if($key==='platforms'){echo '<label>Platform<select name="platform"><option value="">All Platforms</option>';foreach(['Lazada','Shopee','TikTok','Website'] as $platform)echo '<option '.($f['platform']===$platform?'selected':'').'>'.$platform.'</option>';echo '</select></label>';}
 echo '<div class="overview-filter-bottom"><div class="overview-actions">';if(!$master)foreach(['Today'=>date('Y-m-d'),'Yesterday'=>date('Y-m-d',strtotime('-1 day'))] as $label=>$date)echo '<button type="button" class="btn ghost sm" data-sb-date="'.$date.'">'.$label.'</button>';else echo '<span class="small muted">Current records · As Of does not apply</span>';echo '</div><div class="overview-actions"><button class="btn primary" type="submit">Generate Report</button><a class="btn ghost" href="?page=reports&amp;report='.e($key).'">Clear Filters</a></div></div></form></div>';
 echo '<p class="overview-scope">'.e($master?'Current Product Master':report_period_label($f)).' · '.e(report_readable_filters($f)).'</p>';sb_cards($r['summary']);if(!$master)echo '<p class="overview-notice">ⓘ Sellable is not Available to Sell. Current reservations are not mixed into historical quantities. Totals cover all matching products, including inactive items.</p>';
 $negative=count(array_filter($r['balance_report']['details'],fn($d)=>!empty($d['negative'])));if($negative)echo '<div class="alert warn">'.$negative.' matching product(s) have a negative balance at this cutoff. Review the breakdown; no stock is adjusted from this report.</div>';
 if($key==='platforms'&&$r['balance_report']['warnings'])echo '<div class="alert warn">'.count($r['balance_report']['warnings']).' product(s) need platform review: negative allocation or Platform Total differs from Sellable. All four allocations are checked, even when viewing one platform.</div>';
 if($key==='restricted'){echo '<div class="alert info">Ledger Non-Sellable: <b>'.number_format($r['summary']['Ending Non-Sellable (pcs)']).' pcs</b> · Source Remaining: <b>'.number_format($r['balance_report']['source_remaining']).' pcs</b>. These are separate views; legacy source availability may be unverified.</div>';}
 echo '<div class="card sb-products"><div class="card-head"><div><h3>'.e($r['title']).'</h3><p>'.number_format($count).' matching products · '.($master?'Current records':e(report_period_label($f)).' · pcs').'</p></div>';sb_exports($r);echo '</div><p class="small muted">Generated '.e($r['generated']).' · '.e($r['user']).'</p><div class="overview-table-scroll"><table class="table sb-list-table" data-server-paginated="1"><thead><tr><th>Product / SKU</th>';foreach(array_slice($r['headers'],2) as $header)echo '<th>'.e($header).'</th>';echo '<th>Action</th></tr></thead><tbody>';
 $canDetail=access_page_allowed('stock_balance_detail')&&access_report_allowed('stock_balance_detail');$context=sb_context($f,$size,$offset);
 foreach(array_slice($r['rows'],$offset,$size,true) as $index=>$row){$d=$r['balance_report']['details'][$index];echo '<tr><td>'.e($row[1]).'<small>'.e($row[0]).'</small>'.(!$d['active']?'<small>Inactive · retained in stock reports</small>':'').(!empty($d['negative'])?'<span class="sb-alert-badge">Negative Balance</span>':'').'</td>';foreach(array_slice($row,2) as $v)echo '<td class="'.(is_int($v)?'overview-number'.($v<0?' sb-negative':''):'').'">'.e(is_int($v)?number_format($v):$v).'</td>';echo '<td>';
  if(!$master&&$canDetail){$link=['page'=>'stock_balance_detail','id'=>$d['id'],'as_of'=>$f['as_of']]+$context;echo '<a class="btn ghost sm" data-sb-breakdown href="?'.e(http_build_query($link)).'">View Breakdown</a>';}
  elseif($master&&access_page_allowed('product_detail'))echo '<a class="btn ghost sm" href="?page=product_detail&amp;id='.$d['id'].'">View Product</a>';
  else echo '<span class="small muted">Read-only</span>';echo '</td></tr>';
 }
 if(!$count)echo '<tr><td colspan="'.count($r['headers']).'">No matching products. Adjust the filters.</td></tr>';echo '</tbody>';if($r['totals_row']){echo '<tfoot><tr><td>'.e($r['totals_row'][1]).' · '.number_format($count).' products</td>';foreach(array_slice($r['totals_row'],2) as $v)echo '<td class="'.(is_int($v)?'overview-number':'').'">'.e(is_int($v)?number_format($v):$v).'</td>';echo '<td></td></tr></tfoot>';}echo '</table></div>';sb_pager($count,$size,$offset,$query);echo '</div>';if($key==='restricted')sb_render_sources($r);sb_notes_html($r['notes']);echo '</div>';
}
function sb_detail_page($pid,$date){
 if(!$pid)throw new Exception('Select a product for the stock balance breakdown.');$r=inventory_report_build(['report'=>'stock_balance_detail','product_id'=>$pid,'as_of'=>$date]);$p=$r['balance_report']['product'];$return=sb_return_query($_GET);$size=sb_page_size();$count=count($r['rows']);$offset=sb_offset($count,$size);sb_assets();echo '<div class="overview-report sb-report">';sb_nav($r['filters']);echo '<div class="page-head"><div><h1>Stock Balance Breakdown</h1><p>'.e($p['name'].' · '.$p['master_sku']).'</p><p>'.e(report_period_label($r['filters'])).' · Quantities in pcs</p></div><a class="btn ghost" data-sb-back href="?'.e(http_build_query($return)).'">Back to Stock Balance</a></div>';sb_cards($r['summary']);
 echo '<div class="card"><details class="sb-reconciliation" open><summary>Balance Reconciliation</summary>'.overview_matrix_html($r['balance_report']['rollforward'],['from'=>$r['balance_report']['roll_from'],'to'=>$date]).'</details></div>';
 echo '<div class="card sb-products"><div class="card-head"><div><h3>Movement History</h3><p>'.number_format($count).' posted ledger entries through '.e($date).' · All three running balances are retained across pages.</p></div>';sb_exports($r);echo '</div><div class="overview-table-scroll"><table class="table sb-history-table" data-server-paginated="1"><thead><tr><th>Date / Recorded At</th><th>Movement / Reference</th><th>Sellable Change</th><th>Non-Sellable Change</th><th>Sellable Balance</th><th>Non-Sellable Balance</th><th>Physical Balance</th><th>Source</th></tr></thead><tbody>';
 foreach(array_slice($r['rows'],$offset,$size,true) as $i=>$row){echo '<tr><td>'.e($row[0]).'<small>'.e($row[1]).'</small></td><td>'.e($row[2]).'<small>'.e($row[3]).'</small></td>';foreach(array_slice($row,4) as $col=>$v)echo '<td class="overview-number '.($v<0?'sb-negative':($col<2&&$v>0?'overview-plus':'')).'">'.e($col<2?overview_signed($v):number_format($v)).'</td>';echo '<td>'.(!empty($r['links'][$i])?'<a class="btn ghost sm" href="'.e($r['links'][$i]).'">View Source</a>':'—').'</td></tr>';}
 if(!$count)echo '<tr><td colspan="8">No posted movements through this cutoff. Ending balances are zero.</td></tr>';echo '</tbody></table></div>';$params=array_replace($_GET,['page'=>'stock_balance_detail','id'=>$pid,'as_of'=>$date]);unset($params['product_id']);sb_pager($count,$size,$offset,$params);echo '</div>';sb_render_sources($r);sb_notes_html($r['notes']);echo '</div>';
}
